def evidence(m,src,status,unresolved):
 ap={'Scope':'Model','Models':[m['BoatModelID']],'Years':{'From':m.get('FirstYear'),'To':m.get('LastYear')},'Variations':[]}
 m['EvidenceSummary']={'KnowledgeCoverage':'Strong' if status=='Reviewed' else 'Partial','EvidenceQuality':'Moderate' if src else 'Low','Statements':[
 {'Scope':'IdentityAndDimensions','AppliesTo':deepcopy(ap),'EvidenceRefs':src,'EvidenceTypes':['Factory documented','Technical or survey source'],'Confidence':'High' if status=='Reviewed' else 'Moderate','Notes':'Identity and representative specifications are based on model-specific documentation.'},
 {'Scope':'OverviewAndSuitability','AppliesTo':deepcopy(ap),'EvidenceRefs':src,'EvidenceTypes':['Factory documented','Technical or survey source'],'Confidence':'Moderate','Notes':'Guidance is derived from documented layout, hull and propulsion characteristics.'},
 {'Scope':'InspectionFocus','AppliesTo':dict(ap,Scope='Model family'),'EvidenceRefs':src,'EvidenceTypes':['Technical or survey source'],'Confidence':'Moderate','Notes':'Inspection guidance addresses configuration and age risks and is not a claim of universal model defects.'}],
 'UnresolvedInformation':unresolved+['Legacy CommonProblems were not promoted to KnownConcerns without model-specific evidence meeting the approved threshold.']}
 m.update(ResearchStatus=status,DataConfidence='Moderate' if status=='Reviewed' else 'Low',ReviewedBy='B-Scout Phase 8C-13 Scandinavian Research',LastUpdated=today,Revision=(m.get('Revision') or 1)+1)

def suit(m,character='coastal'):
 return {'CoupleCruising':{'Assessment':'Good','Summary':'The documented accommodation and protected helm arrangement suit a cruising couple.'},'SoloHandling':{'Assessment':'Good' if (m.get('EngineCount')==1 and (m.get('LOA_ft') or 99)<=40) else 'Mixed','Summary':'Visibility is generally strong; docking burden depends on size, propulsion and fitted thrusters.'},'InlandWaterways':{'Assessment':'Good' if (m.get('Beam_ft') or 99)<=12 else 'Mixed','Summary':'Dimensions suit many inland routes, but air draft and speed-oriented propulsion remain route-specific.'},'ExposedWater':{'Assessment':'Good' if character in ['coastal','all-weather'] else 'Mixed','Summary':'Scandinavian designs emphasize protected operation, but model-specific CE category, loading and condition govern exposed-water suitability.'}}

def norm(m,overview,strengths,trade,best,avoid,insp,vars,src,status='Reviewed',unresolved=[]):
 m['Overview']=overview;m['Suitability']=suit(m,'all-weather' if m['Manufacturer'] in ['Nord Star','Nimbus'] else 'coastal');m['Strengths']=strengths;m['TradeOffs']=trade;m['BestFor']=best;m['AvoidIf']=avoid;m['KnownConcerns']=[];m['InspectionFocus']=insp;m['BuyerQuestions']=[f'What inspection, service or repair history is available for {x[0].lower()+x[1:]}?' for x in insp];m['OwnerActions']=['Keep windows, deck hardware, hatches and exterior penetrations sealed','Maintain propulsion, cooling, exhaust, steering and electrical systems to documented intervals','Document propulsion, battery and system upgrades for future survey and resale'];m['ModelVariations']=vars;evidence(m,src,status,unresolved)
 m['ResearchNotes']='\n\n'.join(x for x in [f'Phase 8C-13 Scandinavian normalization {today}.',(m.get('ResearchNotes') or '').strip()] if x)

